{
  "explanation": "The rational function f(x) = (2x + 1)/(x - 3) has a vertical asymptote where the denominator is zero (x = 3) and a horizontal asymptote y = 2, found by dividing leading coefficients of the equal-degree numerator and denominator. The graph approaches these lines but never crosses the vertical asymptote, creating two separate branches.",
  "manimCode": "const ax = new Axes({
  xRange: [-6, 12, 2],
  yRange: [-8, 12, 2],
  xLength: 11,
  yLength: 6.5,
  tips: true
});
ax.moveTo([0.3, 0.2, 0]);

const labels = ax.getAxisLabels('x', 'y');

const leftBranch = ax.plot(x => (2 * x + 1) / (x - 3), {
  color: BLUE,
  xRange: [-6, 2.85],
  numSamples: 400
});
const rightBranch = ax.plot(x => (2 * x + 1) / (x - 3), {
  color: BLUE,
  xRange: [3.15, 12],
  numSamples: 400
});

const vAsymp = new Line({
  start: ax.c2p(3, -8),
  end: ax.c2p(3, 12),
  color: RED
});
vAsymp.setStrokeWidth(2).setOpacity(0.85);

const hAsymp = new Line({
  start: ax.c2p(-6, 2),
  end: ax.c2p(12, 2),
  color: ORANGE
});
hAsymp.setStrokeWidth(2).setOpacity(0.85);

const title = new MathTex({ latex: 'f(x) = \\frac{2x+1}{x-3}' });
await title.waitForRender();
title.scale(0.85);
title.moveTo([-3.8, 3.4, 0]);

const vLabel = new MathTex({ latex: 'x = 3' });
await vLabel.waitForRender();
vLabel.scale(0.65);
vLabel.setColor(RED);
vLabel.moveTo(ax.c2p(3, 10.5));
vLabel.shift([0.9, 0, 0]);

const hLabel = new MathTex({ latex: 'y = 2' });
await hLabel.waitForRender();
hLabel.scale(0.65);
hLabel.setColor(ORANGE);
hLabel.moveTo(ax.c2p(10.5, 2));
hLabel.shift([0, 0.45, 0]);

scene.add(ax, labels, vAsymp, hAsymp, leftBranch, rightBranch, title, vLabel, hLabel);

const t = new ValueTracker(5);
const trackerDot = new Dot({ color: YELLOW });
trackerDot.addUpdater(() => {
  const x = t.getValue();
  if (Math.abs(x - 3) < 0.2) return;
  trackerDot.moveTo(ax.c2p(x, (2 * x + 1) / (x - 3)));
});
scene.add(trackerDot);

const controls = new Controls(scene, { position: 'bottom-left', width: 260 });
controls.addSlider({
  label: 'x on curve',
  min: -5,
  max: 11,
  value: 5,
  step: 0.05,
  onChange: (val) => {
    if (Math.abs(val - 3) >= 0.15) t.setValue(val);
  }
});
controls.addCheckbox({
  label: 'Show asymptotes',
  checked: true,
  onChange: (checked) => {
    vAsymp.setOpacity(checked ? 0.85 : 0);
    hAsymp.setOpacity(checked ? 0.85 : 0);
    vLabel.setOpacity(checked ? 1 : 0);
    hLabel.setOpacity(checked ? 1 : 0);
  }
});

await scene.wait(999999);"
}

